import java.util.*;

public class Main {
    public static void main(String[] args) {
        Ledger ledger = new Ledger();
        PaymentService paymentService = new PaymentService(ledger);

        // A genuinely new payment: customer pays a merchant 5000 minor units (e.g. $50.00).
        PaymentResult first = paymentService.charge("idem-key-1", "customer-1", "merchant-1", 5000);
        System.out.println("First charge: " + first.status + ", paymentId=" + first.paymentId);

        // The exact same idempotency key is retried, simulating a client timeout-and-resend.
        PaymentResult retried = paymentService.charge("idem-key-1", "customer-1", "merchant-1", 5000);
        System.out.println("Retried charge: " + retried.status + ", paymentId=" + retried.paymentId);
        System.out.println("Same payment returned, not double charged: " + (first.paymentId.equals(retried.paymentId)));

        // A different, genuinely new payment for the same customer.
        PaymentResult second = paymentService.charge("idem-key-2", "customer-1", "merchant-1", 1500);
        System.out.println("Second charge: " + second.status + ", paymentId=" + second.paymentId);

        System.out.println("Customer balance change: " + ledger.balanceOf("customer-1"));
        System.out.println("Merchant balance change: " + ledger.balanceOf("merchant-1"));
        System.out.println("Ledger totals balance, debits equal credits: " + ledger.isBalanced());
        System.out.println("Total transactions actually posted (retry did not create a third): " + ledger.transactionCount());
    }
}

// The outcome of a charge attempt: either genuinely new, or the cached result
// of an already-processed idempotency key.
class PaymentResult {
    String paymentId;
    String status;

    PaymentResult(String paymentId, String status) {
        this.paymentId = paymentId;
        this.status = status;
    }
}

// Coordinates a payment: checks idempotency first, then posts a balanced debit
// and credit to the ledger only for a genuinely new request.
class PaymentService {
    private final Ledger ledger;
    private final Map<String, PaymentResult> resultsByIdempotencyKey = new HashMap<>(); // idempotency key -> original result
    private int nextPaymentId = 1;

    PaymentService(Ledger ledger) {
        this.ledger = ledger;
    }

    // Charges fromAccount and pays toAccount, unless idempotencyKey has already
    // been processed, in which case the original result is returned untouched.
    PaymentResult charge(String idempotencyKey, String fromAccount, String toAccount, long amountMinorUnits) {
        PaymentResult existing = resultsByIdempotencyKey.get(idempotencyKey);
        if (existing != null) {
            return existing; // a retry; return the original result, post nothing new to the ledger
        }

        String paymentId = "payment-" + (nextPaymentId++);
        ledger.postTransaction(paymentId, fromAccount, toAccount, amountMinorUnits); // one atomic debit and credit
        PaymentResult result = new PaymentResult(paymentId, "SUCCEEDED");
        resultsByIdempotencyKey.put(idempotencyKey, result); // remember this key's result for any future retry
        return result;
    }
}

// A durable, append-only double-entry ledger: every transaction posts exactly
// one debit and one matching credit, so total debits always equal total credits.
class Ledger {
    private final List<LedgerEntry> entries = new ArrayList<>(); // every entry ever posted, never edited or removed
    private int transactionCount = 0;

    // Posts one balanced transaction: a debit against fromAccount and an equal
    // credit against toAccount, as a single atomic operation.
    void postTransaction(String paymentId, String fromAccount, String toAccount, long amountMinorUnits) {
        entries.add(new LedgerEntry(paymentId, fromAccount, "DEBIT", amountMinorUnits));
        entries.add(new LedgerEntry(paymentId, toAccount, "CREDIT", amountMinorUnits));
        transactionCount++;
    }

    // Net balance change for one account: credits increase it, debits decrease it.
    long balanceOf(String accountId) {
        long balance = 0;
        for (LedgerEntry entry : entries) {
            if (!entry.accountId.equals(accountId)) continue;
            balance += entry.direction.equals("CREDIT") ? entry.amountMinorUnits : -entry.amountMinorUnits;
        }
        return balance;
    }

    // Verifies the fundamental accounting invariant across the whole ledger.
    boolean isBalanced() {
        long totalDebits = 0;
        long totalCredits = 0;
        for (LedgerEntry entry : entries) {
            if (entry.direction.equals("DEBIT")) totalDebits += entry.amountMinorUnits;
            else totalCredits += entry.amountMinorUnits;
        }
        return totalDebits == totalCredits;
    }

    int transactionCount() {
        return transactionCount;
    }
}

// One half of a balanced transaction: either a debit or a credit against one account.
class LedgerEntry {
    String paymentId;         // which payment produced this entry
    String accountId;         // which account this entry affects
    String direction;          // "DEBIT" or "CREDIT"
    long amountMinorUnits;      // the amount, in integer minor units to avoid rounding errors

    LedgerEntry(String paymentId, String accountId, String direction, long amountMinorUnits) {
        this.paymentId = paymentId;
        this.accountId = accountId;
        this.direction = direction;
