// A durable, append-only double-entry ledger: every transaction posts exactly
// one debit and one matching credit, so total debits always equal total credits.
class Ledger {
public:
    // Posts one balanced transaction: a debit against fromAccount and an equal
    // credit against toAccount, as a single atomic operation.
    void postTransaction(const std::string& paymentId, const std::string& fromAccount, const std::string& toAccount, long long amountMinorUnits) {
        entries_.push_back({ paymentId, fromAccount, "DEBIT", amountMinorUnits });
        entries_.push_back({ paymentId, toAccount, "CREDIT", amountMinorUnits });
        transactionCount_++;
    }

    // Net balance change for one account: credits increase it, debits decrease it.
    long long balanceOf(const std::string& accountId) {
        long long balance = 0;
        for (auto& entry : entries_) {
            if (entry.accountId != accountId) continue;
            balance += entry.direction == "CREDIT" ? entry.amountMinorUnits : -entry.amountMinorUnits;
        }
        return balance;
    }

    // Verifies the fundamental accounting invariant across the whole ledger.
    bool isBalanced() {
        long long totalDebits = 0;
        long long totalCredits = 0;
        for (auto& entry : entries_) {
            if (entry.direction == "DEBIT") totalDebits += entry.amountMinorUnits;
            else totalCredits += entry.amountMinorUnits;
        }
        return totalDebits == totalCredits;
    }

    int transactionCount() const { return transactionCount_; }

private:
    std::vector<LedgerEntry> entries_;   // every entry ever posted, never edited or removed
    int transactionCount_ = 0;
};

// Coordinates a payment: checks idempotency first, then posts a balanced debit
// and credit to the ledger only for a genuinely new request.
class PaymentService {
public:
    explicit PaymentService(Ledger* ledger) : ledger_(ledger) {}

    // Charges fromAccount and pays toAccount, unless idempotencyKey has already
    // been processed, in which case the original result is returned untouched.
    PaymentResult charge(const std::string& idempotencyKey, const std::string& fromAccount, const std::string& toAccount, long long amountMinorUnits) {
        auto it = resultsByIdempotencyKey_.find(idempotencyKey);
        if (it != resultsByIdempotencyKey_.end()) {
            return it->second;   // a retry; return the original result, post nothing new to the ledger
        }

        std::string paymentId = "payment-" + std::to_string(nextPaymentId_++);
        ledger_->postTransaction(paymentId, fromAccount, toAccount, amountMinorUnits);   // one atomic debit and credit
        PaymentResult result{ paymentId, "SUCCEEDED" };
        resultsByIdempotencyKey_[idempotencyKey] = result;   // remember this key's result for any future retry
        return result;
    }

private:
    Ledger* ledger_;
    std::map<std::string, PaymentResult> resultsByIdempotencyKey_;   // idempotency key -> original result
    int nextPaymentId_ = 1;
};

int main() {
    std::cout << std::boolalpha;
    Ledger ledger;
    PaymentService paymentService(&ledger);

    // A genuinely new payment: customer pays a merchant 5000 minor units (e.g. $50.00).
    PaymentResult first = paymentService.charge("idem-key-1", "customer-1", "merchant-1", 5000);
    std::cout << "First charge: " << first.status << ", paymentId=" << first.paymentId << "\n";

    // The exact same idempotency key is retried, simulating a client timeout-and-resend.
    PaymentResult retried = paymentService.charge("idem-key-1", "customer-1", "merchant-1", 5000);
    std::cout << "Retried charge: " << retried.status << ", paymentId=" << retried.paymentId << "\n";
    std::cout << "Same payment returned, not double charged: " << (first.paymentId == retried.paymentId) << "\n";

    // A different, genuinely new payment for the same customer.
    PaymentResult second = paymentService.charge("idem-key-2", "customer-1", "merchant-1", 1500);
    std::cout << "Second charge: " << second.status << ", paymentId=" << second.paymentId << "\n";

    std::cout << "Customer balance change: " << ledger.balanceOf("customer-1") << "\n";
    std::cout << "Merchant balance change: " << ledger.balanceOf("merchant-1") << "\n";
    std::cout << "Ledger totals balance, debits equal credits: " << ledger.isBalanced() << "\n";
    std::cout << "Total transactions actually posted (retry did not create a third): " << ledger.transactionCount() << "\n";
    return 0;
}

